# super() - 代理父类方法
class Animal:
    def speak(self):
        return '...'

class Dog(Animal):
    def speak(self):
        return super().speak() + ' 汪!'

dog = Dog()
print(dog.speak())  # ... 汪!

# property - 创建托管属性
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError('半径不能为负')
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.radius)   # 5
print(c.area)     # 78.53975
c.radius = 10
print(c.area)     # 314.159

# classmethod - 类方法
class Date:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @classmethod
    def from_string(cls, date_str):
        y, m, d = map(int, date_str.split('-'))
        return cls(y, m, d)

d = Date.from_string('2024-01-15')
print(d.year, d.month, d.day)  # 2024 1 15

# staticmethod - 静态方法
class MathHelper:
    @staticmethod
    def add(a, b):
        return a + b

print(MathHelper.add(3, 4))  # 7
